<table class="gt_table" data-quarto-disable-processing="false" data-quarto-bootstrap="false">
  <thead>
    <tr class="gt_col_headings">
      <th class="gt_col_heading gt_columns_bottom_border gt_left" rowspan="1" colspan="1" style="color: #A9A9A9; font-family: 'Source Sans Pro'; text-transform: uppercase;" scope="col" id="Model_Type">Model type</th>
      <th class="gt_col_heading gt_columns_bottom_border gt_left" rowspan="1" colspan="1" style="color: #A9A9A9; font-family: 'Source Sans Pro'; text-transform: uppercase;" scope="col" id="Core_Methodology">Core methodology</th>
      <th class="gt_col_heading gt_columns_bottom_border gt_left" rowspan="1" colspan="1" style="color: #A9A9A9; font-family: 'Source Sans Pro'; text-transform: uppercase;" scope="col" id="Key_Features">Key features</th>
      <th class="gt_col_heading gt_columns_bottom_border gt_left" rowspan="1" colspan="1" style="color: #A9A9A9; font-family: 'Source Sans Pro'; text-transform: uppercase;" scope="col" id="Common_Use_Cases">Common use cases</th>
      <th class="gt_col_heading gt_columns_bottom_border gt_left" rowspan="1" colspan="1" style="color: #A9A9A9; font-family: 'Source Sans Pro'; text-transform: uppercase;" scope="col" id="Strengths">Strengths</th>
      <th class="gt_col_heading gt_columns_bottom_border gt_left" rowspan="1" colspan="1" style="color: #A9A9A9; font-family: 'Source Sans Pro'; text-transform: uppercase;" scope="col" id="Limitations">Limitations</th>
    </tr>
  </thead>
  <tbody class="gt_table_body">
    <tr><td headers="Model_Type" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Compartmental Models (e.g., SIR, SEIR, SEIRS)</td>
<td headers="Core_Methodology" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Differential equations representing population movement between disease states</td>
<td headers="Key_Features" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Populations divided into compartments (Susceptible, Exposed, Infectious, Recovered, etc.)</td>
<td headers="Common_Use_Cases" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Modelling transmission dynamics, intervention evaluation</td>
<td headers="Strengths" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Simple, interpretable, computationally efficient</td>
<td headers="Limitations" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Assumes homogeneous mixing, limited individual variation</td></tr>
    <tr><td headers="Model_Type" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Age-structured / Demographic Models</td>
<td headers="Core_Methodology" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Extends compartmental models with age or risk group stratification</td>
<td headers="Key_Features" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Tracks population by age, sex, or risk</td>
<td headers="Common_Use_Cases" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Intervention evaluation with comparison between age or risk groups</td>
<td headers="Strengths" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Captures heterogeneity, informs targeted interventions</td>
<td headers="Limitations" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Requires detailed data, increases complexity</td></tr>
    <tr><td headers="Model_Type" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Spatial / Metapopulation Models</td>
<td headers="Core_Methodology" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Divides populations into spatial units connected by movement</td>
<td headers="Key_Features" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Incorporates travel, migration, or vector dispersal</td>
<td headers="Common_Use_Cases" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Regional transmission, outbreak spread, importation risk</td>
<td headers="Strengths" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Models geography and connectivity explicitly</td>
<td headers="Limitations" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Computationally demanding, needs spatial data</td></tr>
    <tr><td headers="Model_Type" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Vector-borne Transmission Models</td>
<td headers="Core_Methodology" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Links human and vector populations via transmission parameters</td>
<td headers="Key_Features" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Includes mosquito, tick, or other vector compartments</td>
<td headers="Common_Use_Cases" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Malaria, dengue, Zika</td>
<td headers="Strengths" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Represents human–vector interaction explicitly</td>
<td headers="Limitations" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Requires vector data (biting rate, survival, distribution etc.)</td></tr>
    <tr><td headers="Model_Type" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Stochastic Models</td>
<td headers="Core_Methodology" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Adds randomness to transmission and progression processes</td>
<td headers="Key_Features" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Uses probabilities instead of deterministic rates</td>
<td headers="Common_Use_Cases" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Small populations, early outbreak dynamics</td>
<td headers="Strengths" class="gt_row gt_left" style="font-family: 'Source Sans Pro'; font-weight: 400;">Captures chance events, extinction probabilities</td>
